mapper.select:
SELECT MAX(CAST(SUBSTRING(reliability_data_form_no, 10, 3) AS UNSIGNED))
FROM efvs_reliability_data
WHERE SUBSTRING(reliability_data_form_no, 2, 8) = #{dateStr}

SELECT * FROM efvs_reliability_data WHERE sru_number IN
#{partNumber}
AND level = 2 AND deleted = 0 AND is_product_issue = 1 AND tenant_id = #{tenantId}

SELECT MAX(part_name) AS partName, MAX(serial_number) AS serialNumber, part_number AS partNumber, MAX(removal_date) AS removalDate, COUNT(*) AS issueCount, MAX(report_start_date) AS reportStartDate, SUBSTRING_INDEX( GROUP_CONCAT(failure_description ORDER BY create_time DESC SEPARATOR '|||'), '|||', 1 ) AS failureDescription, MAX(create_time) AS createTime FROM efvs_reliability_data WHERE deleted = 0 AND is_product_issue = 1 AND tenant_id = #{tenantId}
AND part_name LIKE CONCAT('%', #{partName}, '%')
AND part_number = #{partNumber}
AND removal_date >= #{startTime}
AND removal_date <= #{endTime}
GROUP BY part_number ORDER BY MAX(create_time) DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(1)
FROM (
    SELECT 1
    FROM efvs_reliability_data
    WHERE deleted = 0
      AND is_product_issue = 1
      AND tenant_id = #{tenantId}

        AND part_name LIKE CONCAT('%', #{partName}, '%')


        AND part_number = #{partNumber}


    AND removal_date >= #{startTime}


    AND removal_date <= #{endTime}

    GROUP BY part_number
) t
